#!/usr/bin/env python3
"""QA script: inspect final_deck.pptx for content and layout issues."""

from pptx import Presentation
from pptx.util import Inches, Emu
import os

OUTPUT = "/app/output/final_deck.pptx"
prs = Presentation(OUTPUT)

SLD_W = prs.slide_width
SLD_H = prs.slide_height
print(f"Slide dimensions: {SLD_W} x {SLD_H} EMU = {SLD_W / 914400:.2f} x {SLD_H / 914400:.2f} inches")
print(f"Total slides: {len(prs.slides)}")
print()

issues = []

for i, slide in enumerate(prs.slides):
    print(f"=== Slide {i+1} ===")
    shapes = list(slide.shapes)
    print(f"  Shapes: {len(shapes)}")

    texts_found = []
    for s in shapes:
        # Check out-of-bounds
        if s.left is not None and s.top is not None:
            right = s.left + s.width
            bottom = s.top + s.height
            if right > SLD_W + Emu(50000):
                issues.append(f"  Slide {i+1}: shape '{s.name}' right edge ({right/914400:.2f}in) exceeds slide width ({SLD_W/914400:.2f}in)")
            if bottom > SLD_H + Emu(50000):
                issues.append(f"  Slide {i+1}: shape '{s.name}' bottom edge ({bottom/914400:.2f}in) exceeds slide height ({SLD_H/914400:.2f}in)")

        if s.has_text_frame:
            for p in s.text_frame.paragraphs:
                t = p.text.strip()
                if t:
                    texts_found.append(t[:80])
                    # Check for placeholder/template junk
                    for junk in ["Click to", "Lorem ipsum", "Sample", "placeholder", "Type here"]:
                        if junk.lower() in t.lower():
                            issues.append(f"  Slide {i+1}: possible template junk: '{t[:60]}'")

        if s.has_chart:
            print(f"  Chart found: {s.chart.chart_type}")

        if s.has_table:
            tbl = s.table
            print(f"  Table: {len(tbl.rows)} rows x {len(tbl.columns)} cols")
            for r in range(len(tbl.rows)):
                row_text = [tbl.cell(r, c).text for c in range(len(tbl.columns))]
                print(f"    Row {r}: {row_text}")

        if hasattr(s, 'image'):
            print(f"  Image: {s.image.content_type}")

    for t in texts_found[:5]:
        print(f"  Text: {t}")
    if len(texts_found) > 5:
        print(f"  ... and {len(texts_found)-5} more text items")
    print()

if issues:
    print("=== ISSUES FOUND ===")
    for iss in issues:
        print(iss)
else:
    print("=== NO ISSUES FOUND ===")

# Check all required figures are embedded
print("\n=== Image Check ===")
image_count = 0
for i, slide in enumerate(prs.slides):
    for s in slide.shapes:
        if hasattr(s, 'image'):
            image_count += 1
            print(f"  Slide {i+1}: image ({s.image.content_type}, {s.width/914400:.1f}x{s.height/914400:.1f} in)")
print(f"Total images: {image_count} (expected: 5)")

